    $stage_json$::jsonb
  ) as seed(
    "achievementId" text,
    "stageNumber" int,
    requirement text,
    target jsonb,
    "rewardCurrency" int,
    "rewardStars" int,
    "rewardExperience" int,
    "rewardTokens" int
  )
)
insert into achievement_stages
  (achievement_id, stage_number, requirement, target, reward_currency, reward_stars,
   reward_experience, reward_tokens, is_enabled)
select "achievementId", "stageNumber", requirement, target, "rewardCurrency", "rewardStars",
       "rewardExperience", 0, true
  from stage_seed
on conflict (achievement_id, stage_number) do update
   set requirement = excluded.requirement,
       target = excluded.target,
       reward_currency = excluded.reward_currency,
       reward_stars = excluded.reward_stars,
       reward_experience = excluded.reward_experience,
       reward_tokens = 0,
       is_enabled = true,
       updated_at = now();

update achievements
   set requirement = 'Проиграть сопернику и в следующей дуэли снова сыграть именно с ним и победить.'
 where id = 'revenge';
update achievements
   set requirement = 'Выиграть серию плей-офф после отставания в две победы.'
 where id = 'series-comeback';
update achievements set availability = 'hidden' where id = 'tournament-streak';

create table if not exists achievement_mechanics_reconciliation_run (
  run_id uuid primary key,
  audit_hash text not null,
  backup_marker text not null,
  target_user_count integer not null check (target_user_count >= 0),
  applied_at timestamptz not null default now()
);

create table if not exists achievement_mechanics_reconciliation_adjustment (
  run_id uuid not null references achievement_mechanics_reconciliation_run(run_id) on delete restrict,
  user_id uuid not null references users(id) on delete restrict,
  currency_delta integer not null default 0,
  stars_delta integer not null default 0,
  experience_delta integer not null default 0,
  tokens_delta integer not null default 0,
  tokens_award_reconciled integer not null default 0 check (tokens_award_reconciled >= 0),
  balances_after jsonb not null,
  removed_stages jsonb not null default '[]'::jsonb,
  created_at timestamptz not null default now(),
  primary key (run_id, user_id)
);
